codeExamples.java:
public class Main {
    public static void main(String[] args) {
        int a = 15;
        int b = 4;
        int sumVal = a + b;
        double divVal = (double) a / b;
        int floorVal = a / b;
        int remVal = a % b;
        boolean isGreater = a > b;
        System.out.println("Sum: " + sumVal + ", Div: " + divVal + ", Rem: " + remVal);
    }
}

