#include <iostream>
int main() {
    int a = 15, b = 4;
    int sumVal = a + b;
    double divVal = static_cast<double>(a) / b;
    int floorVal = a / b;
    int remVal = a % b;
    bool isGreater = a > b;
    std::cout << "Sum: " << sumVal << ", Div: " << divVal << ", Rem: " << remVal << std::endl;
    return 0;
}
